SELECT COUNT(*) AS OWN_ACCOUNTS FROM accounts WHERE account_number BETWEEN '40817810000000020061' AND '40817810000000020078';
SELECT status,COUNT(*) AS N FROM transfers WHERE from_account BETWEEN '40817810000000020061' AND '40817810000000020078' GROUP BY status ORDER BY status;
SELECT COUNT(*) AS M12_N FROM transfers WHERE idempotency_key='independent-90008b1-m12';
SELECT t.transfer_id,p.account_number,p.direction,p.posting_type,p.amount FROM transfers t JOIN postings p ON p.transfer_id=t.transfer_id WHERE t.idempotency_key='independent-90008b1-m12';
SELECT from_account,COUNT(*) AS N FROM transfers WHERE from_account IN ('40817810000000020063','40817810000000020064') GROUP BY from_account;
SELECT a.account_number,a.balance,COALESCE(SUM(CASE WHEN p.direction='CREDIT' THEN p.amount ELSE -p.amount END),0) AS BY_POSTINGS FROM accounts a LEFT JOIN postings p ON p.account_number=a.account_number WHERE a.account_number BETWEEN '40817810000000020061' AND '40817810000000020078' GROUP BY a.account_number,a.balance HAVING a.balance<>COALESCE(SUM(CASE WHEN p.direction='CREDIT' THEN p.amount ELSE -p.amount END),0);
SELECT t.transfer_id,t.amount,t.commission,t.amount+t.commission AS EXPECTED_REFUND,COALESCE(SUM(p.amount),0) AS ACTUAL_REFUND FROM transfers t LEFT JOIN postings p ON p.transfer_id=t.transfer_id AND p.account_number=t.from_account AND p.direction='CREDIT' AND p.posting_type='REFUND' WHERE t.status='FAILED' AND t.from_account BETWEEN '40817810000000020061' AND '40817810000000020078' GROUP BY t.transfer_id,t.amount,t.commission HAVING COALESCE(SUM(p.amount),0)<>t.amount+t.commission;
SELECT t.transfer_id,t.amount,t.commission,p.posting_type,p.direction,p.amount AS REFUND FROM transfers t JOIN postings p ON p.transfer_id=t.transfer_id WHERE t.transfer_id='8cbed6d3-2615-43f0-aa33-af04423e61ec' AND p.posting_type='REFUND';
SELECT transfer_id,status FROM transfers WHERE from_account BETWEEN '40817810000000020061' AND '40817810000000020078' AND status='PROCESSING';
